// Local knowledge-base portal of the tulospalvelu audit (phase K-4).
// Static page: reads only window.TIETOPOHJA from data/data.js (generated by
// doc/arkkitehtuuri/tyokalut/portaali.py). No network, no libraries.
(function () {
  "use strict";
  var D = window.TIETOPOHJA;
  var main = document.getElementById("sisalto");
  if (!D) {
    main.innerHTML = '<p class="warn">Dataa ei löydy. Tuota se repon juuresta: ' +
      '<code>python -I doc/arkkitehtuuri/tyokalut/portaali.py .</code> ja lataa sivu uudelleen.</p>';
    return;
  }
  var byId = {};
  D.havainnot.forEach(function (h) { byId[h.id] = h; });
  var packById = {};
  D.kokonaisuudet.forEach(function (p) { packById[p.kk] = p; });
  var dims = D.meta.ulottuvuudet;
  var VAL = { vahvistettu: "Vahvistettu", mahdollinen: "Mahdollinen", ei_perusteltu: "Ei vaikutusta (perusteltu)",
    ei_tiedossa: "Ei tiedossa", ei_sovellu: "Ei sovellu", "": "Ei arvioitu" };
  var PROGRAMS = ["HkKisaWin", "HkMaali", "ViestiWin", "ViestiMaali", "ViestiLuenta"];

  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
  function pill(p) { return p && p !== "-" ? '<span class="pill ' + esc(p) + '">' + esc(p) + "</span>" : "–"; }
  function link(id) { return '<a href="#/kortti/' + esc(id) + '">' + esc(id) + "</a>"; }
  function count(list, f) { var c = {}; list.forEach(function (x) { var k = f(x); c[k] = (c[k] || 0) + 1; }); return c; }
  function uniq(a) { return a.filter(function (x, i) { return a.indexOf(x) === i; }); }
  function copyText(text, btn) {
    function done() { if (btn) { var t = btn.textContent; btn.textContent = "Kopioitu"; setTimeout(function () { btn.textContent = t; }, 1500); } }
    if (navigator.clipboard && window.isSecureContext) { navigator.clipboard.writeText(text).then(done, fallback); }
    else { fallback(); }
    function fallback() {
      var ta = document.createElement("textarea"); ta.value = text; ta.className = "copy";
      document.body.appendChild(ta); ta.select();
      var ok = false; try { ok = document.execCommand("copy"); } catch (e) { ok = false; }
      document.body.removeChild(ta);
      if (ok) { done(); } else { window.prompt("Kopioi teksti (Ctrl+C):", text); }
    }
  }
  // coverage figures are computed from the data (rekisteri/tiedostot.csv), never written here
  var COV = (function () {
    var lines = 0, l1 = 0, full = 0;
    Object.keys(D.kattavuus).forEach(function (k) {
      var d = D.kattavuus[k]; lines += d.rivit; l1 += d.r1 || 0;
      if (k !== "Tests" && k !== "VS") { full += d["4"] || 0; }
    });
    var tot = (D.kattavuus_funktiot || []).filter(function (r) { return r.hakemisto === "YHTEENSA"; })[0];
    var noref = tot && +tot.funktiorivit ? Math.round(100 * tot.ei_viitteita_r / tot.funktiorivit) : null;
    return { share1: lines ? Math.round(100 * l1 / lines) : 0, full: full, noref: noref };
  })();
  var COVERAGE = '<p class="coverage"><strong>Kattavuusrajoite:</strong> auditointi ei kata koko lähdekoodia. ' +
    (COV.noref !== null ? "Tunnistetuista funktioriveistä " + COV.noref + " % on sellaisia, joihin ei ole viitattu yhdessäkään auditoinnin asiakirjassa, ja " : "") +
    COV.share1 + " % kaikista lähdekoodiriveistä on tiedostoissa, jotka on vain inventoitu. Viitattukaan koodi ei ole katselmoitu: " +
    "kokonaan katselmoituja tuotantotiedostoja on " + COV.full + ". Havaintojen määrä on alaraja. " +
    'Kortin puuttuminen ei tarkoita, että toiminto on virheetön. <a href="#/kattavuus">Kattavuus</a></p>';
  var SITE = D.meta.sivusto || "";

  // ------------------------------------------------------------- views ---
  function viewSummary() {
    var H = D.havainnot.filter(function (h) { return h.laji === "H"; });
    var T = D.havainnot.filter(function (h) { return h.laji === "T"; });
    var pr = count(H.filter(function (h) { return h.tila === "avoin"; }), function (h) { return h.prioriteetti; });
    var st = count(D.havainnot, function (h) { return h.tila; });
    var cards = D.havainnot.filter(function (h) { return h.kortti; }).length;
    var s = "<h1>Yhteenveto</h1>" + COVERAGE + '<div class="grid">';
    s += '<div class="stat"><b>' + H.length + "</b>havaintoa (H), joista avoimia " + (st.avoin ? H.filter(function (h) { return h.tila === "avoin"; }).length : 0) + "</div>";
    s += '<div class="stat"><b>' + T.length + "</b>teknisen velan riviä (T)</div>";
    s += '<div class="stat"><b>' + cards + " / " + D.havainnot.length + "</b>vikakorttia kirjoitettu</div>";
    s += '<div class="stat"><b>' + D.kokonaisuudet.filter(function (p) { return p.kk.indexOf("KK-") === 0; }).length + "</b>korjauskokonaisuutta</div>";
    s += '<div class="stat"><b>' + D.paatokset.filter(function (o) { return /^avoin/.test(o.tila); }).length + " / " + D.paatokset.length + "</b>omistajan päätöstä avoinna</div>";
    s += '<div class="stat"><b>' + D.kasikirja.length + "</b>käsikirjan lukua ja aineistoa</div></div>";
    s += "<h2>Avoimet havainnot prioriteetin mukaan</h2><p>";
    ["P1", "P2", "P3", "P4", "P5"].forEach(function (p) { s += '<a href="#/havainnot?prioriteetti=' + p + '">' + pill(p) + " " + (pr[p] || 0) + "</a> &nbsp; "; });
    s += '</p><h2>Tila</h2><p>';
    Object.keys(st).sort().forEach(function (k) { s += '<a href="#/havainnot?tila=' + esc(k) + '">' + esc(k) + "</a> " + st[k] + " &nbsp; "; });
    s += "</p><h2>Kiireellisimmät (P1 ja P2)</h2><table><thead><tr><th>Tunnus</th><th>Kuvaus</th><th>P</th><th>Ohjelmat</th><th>Kokonaisuus</th></tr></thead><tbody>";
    H.filter(function (h) { return h.tila === "avoin" && (h.prioriteetti === "P1" || h.prioriteetti === "P2"); })
      .sort(function (a, b) { return a.prioriteetti.localeCompare(b.prioriteetti) || a.id.localeCompare(b.id); })
      .forEach(function (h) { s += "<tr><td>" + link(h.id) + "</td><td>" + esc(h.otsikko) + "</td><td>" + pill(h.prioriteetti) +
        "</td><td>" + esc(h.ohjelmat.join(", ")) + '</td><td><a href="#/kokonaisuus/' + esc(h.kk) + '">' + esc(h.kk) + "</a></td></tr>"; });
    s += "</tbody></table><h2>Auditoinnin yhteenveto</h2><details><summary>Näytä koko asiakirja (auditoinnin-yhteenveto.md)</summary>" + D.asiakirjat.yhteenveto + "</details>";
    return s;
  }

  var FILTERS = [
    ["laji", "Laji", function (h) { return [h.laji]; }],
    ["ohjelma", "Ohjelma", function (h) { return h.ohjelmat; }],
    ["prioriteetti", "Prioriteetti", function (h) { return [h.prioriteetti]; }],
    ["vakavuus", "Tekninen vakavuus", function (h) { return [h.vakavuus]; }],
    ["tila", "Tila", function (h) { return [h.tila]; }],
    ["todennus", "Todentamistaso", function (h) { return [h.todennus]; }],
    ["juurisyy", "Juurisyy", function (h) { return [h.juurisyy].concat(h.juurisyy_muut); }],
    ["kk", "Korjauskokonaisuus", function (h) { return [h.kk]; }],
    ["era", "Erä", function (h) { return [h.era]; }]
  ];
  function viewFindings(q) {
    var list = D.havainnot.slice();
    var s = "<h1>Havainnot ja tekninen velka</h1>" + COVERAGE + '<div class="filters">';
    FILTERS.forEach(function (f) {
      var vals = uniq([].concat.apply([], D.havainnot.map(f[2]))).filter(Boolean).sort();
      s += "<label>" + f[1] + '<select data-f="' + f[0] + '"><option value="">kaikki</option>' +
        vals.map(function (v) { return '<option' + (q[f[0]] === v ? " selected" : "") + ">" + esc(v) + "</option>"; }).join("") + "</select></label>";
    });
    s += '<label>Käytännön vaikutus<select data-f="vaikutus"><option value="">–</option>' +
      dims.map(function (d) { return "<option value=\"" + d.id + "\"" + (q.vaikutus === d.id ? " selected" : "") + ">" + esc(d.nimi) + "</option>"; }).join("") + "</select></label>";
    s += '<label>Vaikutuksen arvo<select data-f="arvo">' +
      [["vm", "vahvistettu tai mahdollinen"], ["vahvistettu", "vahvistettu"], ["mahdollinen", "mahdollinen"], ["ei_perusteltu", "ei vaikutusta (perusteltu)"],
       ["ei_tiedossa", "ei tiedossa"], ["ei_sovellu", "ei sovellu"], ["", "ei arvioitu"]].map(function (o) {
        return '<option value="' + o[0] + '"' + ((q.arvo || "vm") === o[0] ? " selected" : "") + ">" + o[1] + "</option>"; }).join("") + "</select></label>";
    s += '<label>Teksti<input data-f="teksti" value="' + esc(q.teksti || "") + '"></label></div>';
    list = list.filter(function (h) {
      for (var k = 0; k < FILTERS.length; k++) { var f = FILTERS[k]; if (q[f[0]] && f[2](h).indexOf(q[f[0]]) < 0) { return false; } }
      if (q.vaikutus) {
        var v = h.vaikutukset[q.vaikutus] || ""; var want = q.arvo == null ? "vm" : q.arvo;
        if (want === "vm" ? !(v === "vahvistettu" || v === "mahdollinen") : v !== want) { return false; }
      }
      if (q.teksti) { var t = (h.id + " " + h.otsikko + " " + h.rekisteri + " " + h.md).toLowerCase(); if (t.indexOf(q.teksti.toLowerCase()) < 0) { return false; } }
      return true;
    });
    s += '<p class="note">' + list.length + " riviä. Vaikutussuodatin käyttää rekisteriä <code>vaikutukset.csv</code>; ‘ei arvioitu’ = riviä ei ole arvioitu (ei sama kuin ei vaikutusta).</p>";
    s += "<table><thead><tr><th>Tunnus</th><th>Kuvaus</th><th>Tila</th><th>P</th><th>Vakavuus</th><th>Todennus</th><th>Ohjelmat</th><th>JS</th><th>KK</th></tr></thead><tbody>";
    list.forEach(function (h) {
      s += "<tr><td>" + link(h.id) + (h.kortti ? "" : ' <span class="note">(ei korttia)</span>') + "</td><td>" + esc(h.otsikko) + "</td><td>" + esc(h.tila) + "</td><td>" + pill(h.prioriteetti) +
        "</td><td>" + esc(h.vakavuus) + "</td><td>" + esc(h.todennus) + "</td><td>" + esc(h.ohjelmat.join(" ")) + (h.ohjelmat_peruste === "tiedosto" ? ' <span class="note" title="yläraja: viitatut lähdetiedostot">(yläraja)</span>' : "") +
        "</td><td>" + esc(h.juurisyy) + '</td><td><a href="#/kokonaisuus/' + esc(h.kk) + '">' + esc(h.kk) + "</a></td></tr>";
    });
    s += "</tbody></table>";
    main.innerHTML = s;
    Array.prototype.forEach.call(main.querySelectorAll("[data-f]"), function (el) {
      el.addEventListener("change", function () {
        var nq = {}; Array.prototype.forEach.call(main.querySelectorAll("[data-f]"), function (e) { if (e.value) { nq[e.getAttribute("data-f")] = e.value; } });
        if (!nq.vaikutus) { delete nq.arvo; } else if (!("arvo" in nq)) { nq.arvo = ""; }
        location.hash = "#/havainnot?" + Object.keys(nq).map(function (k) { return k + "=" + encodeURIComponent(nq[k]); }).join("&");
      });
    });
    return null;
  }

  function relatedChapters(id) {
    return D.toiminnot.filter(function (t) { return (" " + (t.havainnot || "") + " ").indexOf(" " + id + " ") >= 0; });
  }
  function viewCard(id, q) {
    var h = byId[id];
    if (!h) { return "<p>Tunnusta " + esc(id) + " ei ole rekisterissä.</p>"; }
    var mode = q.nakyma === "tekninen" ? "tekninen" : "kayttaja";
    var s = '<div class="card"><h1>' + esc(h.id) + " – " + esc(h.otsikko) + "</h1>";
    if (!h.kortti) {
      return s + '<p class="warn">Tälle tunnukselle ei ole vielä kirjoitettu korttia.</p><p><strong>Rekisterin kuvaus:</strong> ' + esc(h.rekisteri) +
        "</p><p>Tila " + esc(h.tila) + ", prioriteetti " + pill(h.prioriteetti) + ", kokonaisuus " + esc(h.kk) + "</p></div>";
    }
    var ask = "/pirila-ask Mitä " + h.id + " tarkoittaa kilpailun järjestäjälle, missä tilanteissa se voi ilmetä, ja onko se korjattu?";
    s += '<div class="tabs"><button data-n="kayttaja" class="' + (mode === "kayttaja" ? "on" : "") + '">Käyttäjänäkymä</button>' +
      '<button data-n="tekninen" class="' + (mode === "tekninen" ? "on" : "") + '">Tekninen näkymä (koko kortti)</button></div>';
    s += '<div class="actions" style="margin:.5rem 0"><button id="kopioi">Kopioi kortti (Markdown)</button><button id="tulosta">Tulosta</button>' +
      '<button id="kysy">Kopioi pirila-ask-kysymys</button>' +
      (SITE ? ' <a href="' + esc(SITE + "laatu/vikakortit/" + h.id + "/") + '">Pysyvä osoite (sivusto)</a>' : "") + "</div>";
    if (h.tila !== "avoin") { s += '<p class="warn">Tila: <strong>' + esc(h.tila) + "</strong>" + (h.korjaus ? " – korjaus: " + esc(h.korjaus) : "") + "</p>"; }
    s += h.yhteenveto;
    s += mode === "tekninen" ? h.tekninen : h.kayttaja;
    var ch = relatedChapters(h.id);
    if (ch.length) {
      s += "<h3>Käsikirjassa</h3><ul>" + ch.map(function (t) { return '<li><a href="#/kasikirja/' + esc(t.luku) + '">' + esc(t.toiminto) + "</a> (" + esc(t.luku) + ")</li>"; }).join("") + "</ul>";
    }
    s += '<p class="note">Rekisteri on ensisijainen lähde; kortti on sen selkokielinen johdannainen. ' +
      (mode === "kayttaja" ? 'Tekniset tiedot, lähdeviitteet ja revisio: <a href="#/kortti/' + esc(id) + '?nakyma=tekninen">tekninen näkymä</a>.' : "") + "</p></div>";
    main.innerHTML = s + COVERAGE;
    Array.prototype.forEach.call(main.querySelectorAll(".tabs button"), function (b) {
      b.addEventListener("click", function () { location.hash = "#/kortti/" + id + (b.getAttribute("data-n") === "tekninen" ? "?nakyma=tekninen" : ""); });
    });
    document.getElementById("kopioi").addEventListener("click", function (e) { copyText(h.md, e.target); });
    document.getElementById("tulosta").addEventListener("click", function () { window.print(); });
    document.getElementById("kysy").addEventListener("click", function (e) { copyText(ask, e.target); });
    return null;
  }

  function viewRoots() {
    var s = "<h1>Juurisyyt</h1><p class=\"note\">Lähde: <code>auditoinnin-yhteenveto.md</code> luku 7; jäsenyys <code>riskiarvio.csv</code> ja <code>tekninen-velka.csv</code> (sarake juurisyy).</p>";
    var roots = D.juurisyyt.concat([{ js: "yksittainen", nimi: "Yksittäiset viat ilman yhteistä juurisyytä", mekanismi: "" }]);
    roots.forEach(function (r) {
      var prim = D.havainnot.filter(function (h) { return h.juurisyy === r.js; });
      var worse = D.havainnot.filter(function (h) { return h.juurisyy_muut.indexOf(r.js) >= 0; });
      s += "<h2>" + esc(r.js) + " " + esc(r.nimi) + "</h2><p>" + esc(r.mekanismi) + "</p><p><strong>Ensisijainen juurisyy (" + prim.length + "):</strong> " +
        prim.map(function (h) { return link(h.id) + " " + pill(h.prioriteetti); }).join(", ") + "</p>" +
        (worse.length ? "<p><strong>Pahentava (" + worse.length + "):</strong> " + worse.map(function (h) { return link(h.id); }).join(", ") + "</p>" : "");
    });
    return s;
  }

  function depSvg() {
    var packs = D.kokonaisuudet.filter(function (p) { return p.kk.indexOf("KK-") === 0; });
    var waves = uniq(packs.map(function (p) { return p.aalto; })).sort(function (a, b) { return a - b; });
    var pos = {}, colW = 170, rowH = 34, maxRows = 0;
    waves.forEach(function (w, ci) {
      var col = packs.filter(function (p) { return p.aalto === w; });
      maxRows = Math.max(maxRows, col.length);
      col.forEach(function (p, ri) { pos[p.kk] = { x: 10 + ci * colW, y: 30 + ri * rowH }; });
    });
    var W = 20 + waves.length * colW, H = 40 + maxRows * rowH;
    var s = '<svg viewBox="0 0 ' + W + " " + H + '" width="' + W + '" height="' + H + '" role="img" aria-label="Korjauskokonaisuuksien riippuvuudet aalloittain">';
    waves.forEach(function (w, ci) { s += '<text x="' + (10 + ci * colW) + '" y="16" font-weight="600">Aalto ' + esc(w) + "</text>"; });
    packs.forEach(function (p) { p.riippuu.forEach(function (d) { if (pos[d] && pos[p.kk]) {
      var a = pos[d], b = pos[p.kk];
      s += '<path class="edge" d="M' + (a.x + 140) + " " + (a.y + 11) + " C " + (a.x + 155) + " " + (a.y + 11) + ", " + (b.x - 15) + " " + (b.y + 11) + ", " + b.x + " " + (b.y + 11) + '"/>';
    } }); });
    packs.forEach(function (p) { var a = pos[p.kk];
      s += '<a href="#/kokonaisuus/' + esc(p.kk) + '"><g class="node"><rect x="' + a.x + '" y="' + a.y + '" width="140" height="22" rx="3"/><text x="' + (a.x + 5) + '" y="' + (a.y + 15) + '">' + esc(p.kk + " " + p.prioriteetti) + "</text></g></a>"; });
    return s + "</svg>";
  }
  function viewPacks() {
    var s = "<h1>Korjauskokonaisuudet</h1><p class=\"note\">Lähde: <code>korjauskokonaisuudet.csv</code>, <code>korjaussuunnitelma.md</code>. Kaikki ovat suunniteltuja, ei toteutettuja, ellei havainnon tila ole korjattu.</p>";
    s += '<div style="overflow:auto">' + depSvg() + '</div><p class="note">Viivat: riippuvuus (riippuu) vasemmalta oikealle.</p>';
    s += "<table><thead><tr><th>KK</th><th>Nimi</th><th>P</th><th>Aalto</th><th>Vaihe</th><th>JS</th><th>Jäseniä</th><th>Riippuu</th><th>OP</th><th>Työmäärä</th></tr></thead><tbody>";
    D.kokonaisuudet.forEach(function (p) {
      s += '<tr><td><a href="#/kokonaisuus/' + esc(p.kk) + '">' + esc(p.kk) + "</a></td><td>" + esc(p.nimi) + "</td><td>" + pill(p.prioriteetti) + "</td><td>" + esc(p.aalto) + "</td><td>" + esc(p.vaihe) +
        "</td><td>" + esc(p.juurisyy.join(" ")) + "</td><td>" + p.jasenet.length + "</td><td>" + esc(p.riippuu.join(" ")) + "</td><td>" + esc(p.op.join(" ")) + "</td><td>" + esc(p.tyomaara) + "</td></tr>";
    });
    return s + "</tbody></table>";
  }
  function viewPack(kk) {
    var p = packById[kk];
    if (!p) { return "<p>Kokonaisuutta " + esc(kk) + " ei ole.</p>"; }
    var s = "<h1>" + esc(p.kk) + " " + esc(p.nimi) + "</h1><p>Prioriteetti " + pill(p.prioriteetti) + ", aalto " + esc(p.aalto) + ", vaihe " + esc(p.vaihe) +
      ", työmäärä " + esc(p.tyomaara) + ", muutosriski " + esc(p.muutosriski) + ". Haara <code>" + esc(p.haara) + "</code>.</p>";
    s += "<p><strong>Riippuu:</strong> " + (p.riippuu.map(function (d) { return '<a href="#/kokonaisuus/' + esc(d) + '">' + esc(d) + "</a>"; }).join(", ") || "–") +
      (p.riippuu_osat.length ? "; osittain: " + esc(p.riippuu_osat.join(" ")) : "") + "</p>";
    s += "<p><strong>Omistajan päätökset:</strong> " + (p.op.map(function (o) { return '<a href="#/paatokset/' + esc(o) + '">' + esc(o) + "</a>"; }).join(", ") || "–") +
      " &nbsp; <strong>Kysymykset:</strong> " + esc(p.kysymykset.join(" ") || "–") + " &nbsp; <strong>Testit:</strong> " + esc(p.testit) + "</p>";
    s += "<table><thead><tr><th>Tunnus</th><th>Kuvaus</th><th>Tila</th><th>P</th></tr></thead><tbody>";
    p.jasenet.forEach(function (id) { var h = byId[id] || {}; s += "<tr><td>" + link(id) + "</td><td>" + esc(h.otsikko) + "</td><td>" + esc(h.tila) + "</td><td>" + pill(h.prioriteetti) + "</td></tr>"; });
    return s + "</tbody></table>";
  }
  function viewOps(op) {
    var s = "<h1>Omistajan päätökset</h1><p class=\"note\">Lähde: <code>omistajan-paatokset.md</code>. Päätöksiä ei merkitä tehdyiksi ilman omistajan hyväksyntää.</p>";
    D.paatokset.forEach(function (o) {
      var packs = D.kokonaisuudet.filter(function (p) { return p.op.indexOf(o.op) >= 0; }).map(function (p) { return '<a href="#/kokonaisuus/' + esc(p.kk) + '">' + esc(p.kk) + "</a>"; });
      s += '<details id="' + esc(o.op) + '"' + (op === o.op ? " open" : "") + "><summary><strong>" + esc(o.op) + "</strong> " + esc(o.nimi) + " – <em>" + esc(o.tila) + "</em>" +
        (packs.length ? " · " + packs.join(", ") : "") + "</summary>" + o.html + "</details>";
    });
    return s;
  }
  function viewQuestions() {
    var s = "<h1>Avoimet kysymykset</h1><p class=\"note\">Lähde: <code>seuranta.md</code> (" + esc(D.kysymykset.length ? D.kysymykset[0].q + "–" + D.kysymykset[D.kysymykset.length - 1].q : "") + "). Tila on koneellisesti luettu taulukosta; tarkista epäselvät seuranta.md:stä.</p>";
    var st = count(D.kysymykset, function (q) { return q.tila; });
    s += "<p>" + Object.keys(st).map(function (k) { return esc(k) + " " + st[k]; }).join(" · ") + "</p>";
    s += "<table><thead><tr><th>Q</th><th>Tila</th><th>Kuvaus</th></tr></thead><tbody>";
    D.kysymykset.forEach(function (q) { s += "<tr><td>" + esc(q.q) + "</td><td>" + esc(q.tila) + "</td><td>" + esc(q.kuvaus) + "</td></tr>"; });
    return s + "</tbody></table>";
  }
  function viewProgress() {
    var s = "<h1>Korjausten eteneminen</h1><p class=\"note\">Lähde: sarake <code>tila</code> rekistereissä <code>riskiarvio.csv</code> ja <code>tekninen-velka.csv</code>. D-vaihetta (korjaukset) ei ole aloitettu.</p>";
    s += "<table><thead><tr><th>Aalto</th><th>Kokonaisuus</th><th>Avoin</th><th>Korjattu</th><th>Ei korjata</th><th>Kumottu</th><th>Avoimet OP:t</th></tr></thead><tbody>";
    D.kokonaisuudet.slice().sort(function (a, b) { return (a.aalto || "9").localeCompare(b.aalto || "9") || a.kk.localeCompare(b.kk); }).forEach(function (p) {
      var c = count(p.jasenet.map(function (i) { return byId[i] || {}; }), function (h) { return h.tila; });
      var open = p.op.filter(function (o) { var x = D.paatokset.filter(function (y) { return y.op === o; })[0]; return x && /^avoin/.test(x.tila); });
      s += "<tr><td>" + esc(p.aalto) + '</td><td><a href="#/kokonaisuus/' + esc(p.kk) + '">' + esc(p.kk) + "</a> " + esc(p.nimi) + "</td><td>" + (c.avoin || 0) + "</td><td>" + (c.korjattu || 0) +
        "</td><td>" + (c.ei_korjata || 0) + "</td><td>" + (c.kumottu || 0) + "</td><td>" + esc(open.join(" ")) + "</td></tr>";
    });
    return s + "</tbody></table>";
  }
  function viewTesting() {
    var H = D.havainnot.filter(function (h) { return h.laji === "H"; });
    var c = count(H, function (h) { return h.todennus; });
    var s = "<h1>Testaus ja todennus</h1><h2>Ohjelmointivirheen todentamistaso</h2><table><thead><tr><th>Taso</th><th>Merkitys</th><th>Havaintoja</th></tr></thead><tbody>";
    Object.keys(c).sort().forEach(function (k) { s += '<tr><td><a href="#/havainnot?todennus=' + esc(k) + '">' + esc(k) + "</a></td><td>" + esc(D.meta.todennus[k] || "") + "</td><td>" + c[k] + "</td></tr>"; });
    s += "</tbody></table><h2>Regressiotestaussuunnitelma</h2><details open><summary>regressiotestaussuunnitelma.md</summary>" + D.asiakirjat.regressio + "</details>";
    return s;
  }
  function viewCoverage() {
    var s = "<h1>Kattavuus</h1>" + COVERAGE + "<p class=\"note\">Lähde: <code>tiedostot.csv</code>. Taso 1 = vain inventoitu, 2 = kohdennetusti luettu, 3 = rakenne luettu, 4 = kokonaan katselmoitu (vain testitiedostot).</p>";
    s += "<table><thead><tr><th>Hakemisto</th><th>Tiedostoja</th><th>Rivejä</th><th>Taso 1</th><th>Taso 2</th><th>Taso 3</th><th>Taso 4</th></tr></thead><tbody>";
    Object.keys(D.kattavuus).sort().forEach(function (k) { var d = D.kattavuus[k];
      s += "<tr><td>" + esc(k) + "</td><td>" + d.tiedostot + "</td><td>" + d.rivit + "</td><td>" + (d["1"] || 0) + "</td><td>" + (d["2"] || 0) + "</td><td>" + (d["3"] || 0) + "</td><td>" + (d["4"] || 0) + "</td></tr>"; });
    s += "</tbody></table>";
    var F = D.kattavuus_funktiot || [];
    if (F.length) {
      s += "<h2>Funktiot ja lähdeviitteet</h2><p class=\"note\">Lähde: <code>" + esc(D.meta.kattavuus_lahde) + "/hakemistot.csv</code> " +
        "(<code>tyokalut/kattavuus.py</code>; kaikki tunnistetut funktiot, myös testit). <strong>Viite ei ole katselmointi:</strong> se kertoo vain, " +
        "että kohtaa on katsottu jonkin väitteen vuoksi. Kokonaan katselmoituja funktioita ei ole ennen C-14:ää.</p>";
      s += "<table><thead><tr><th>Hakemisto</th><th>Funktioita</th><th>Rivejä</th><th>Ei viitteitä</th><th>Vain johdettu</th><th>Yksi näkökulma</th><th>Useita</th></tr></thead><tbody>";
      F.forEach(function (r) {
        s += "<tr><td>" + esc(r.hakemisto) + "</td><td>" + esc(r.funktiot) + "</td><td>" + esc(r.funktiorivit) + "</td><td>" + esc(r.ei_viitteita_f) +
          "</td><td>" + esc(r.vain_johdettu_f) + "</td><td>" + esc(r.yksi_nakokulma_f) + "</td><td>" + esc(r.useita_f) + "</td></tr>";
      });
      s += "</tbody></table>";
    }
    if (SITE) { s += '<p>Tarkempi näkymä: <a href="' + esc(SITE + "laatu/kattavuus/") + '">Kattavuus ja rajoitteet</a> (sivusto).</p>'; }
    return s;
  }
  function viewHandbook(id) {
    if (!D.kasikirja.length) { return "<h1>Käsikirja</h1><p>Käsikirjaa ei ole vielä tuotettu.</p>"; }
    if (!id) {
      return "<h1>Toiminnallinen käsikirja</h1><ul>" + D.kasikirja.map(function (c) { return '<li><a href="#/kasikirja/' + esc(c.id) + '">' + esc(c.otsikko) + "</a></li>"; }).join("") + "</ul>" + COVERAGE;
    }
    var c = D.kasikirja.filter(function (x) { return x.id === id; })[0];
    if (!c) { return "<p>Lukua " + esc(id) + " ei ole.</p>"; }
    var fn = D.toiminnot.filter(function (t) { return t.luku === id; });
    var s = '<div class="card"><h1>' + esc(c.otsikko) + "</h1>" + c.html;
    if (fn.length) {
      s += "<h2>Toiminnot ja tunnetut viat (toiminnot.csv)</h2><table><thead><tr><th>Toiminto</th><th>Havainnot</th></tr></thead><tbody>";
      fn.forEach(function (t) { s += "<tr><td>" + esc(t.toiminto) + "</td><td>" + (t.havainnot || "").split(/\s+/).filter(Boolean).map(function (i) {
        var h = byId[i]; return link(i) + (h ? " " + pill(h.prioriteetti) : ""); }).join(", ") + "</td></tr>"; });
      s += "</tbody></table>";
    }
    return s + "</div>" + COVERAGE;
  }
  function viewSearch(q) {
    var term = (q.q || "").toLowerCase().trim();
    var s = "<h1>Haku: " + esc(q.q || "") + "</h1>";
    if (term.length < 2) { return s + "<p>Kirjoita vähintään kaksi merkkiä.</p>"; }
    var hits = [];
    D.havainnot.forEach(function (h) { var t = (h.id + " " + h.otsikko + " " + h.rekisteri + " " + h.md).toLowerCase(); if (t.indexOf(term) >= 0) { hits.push(["Havainto", "#/kortti/" + h.id, h.id + " – " + h.otsikko]); } });
    D.kasikirja.forEach(function (c) { if (c.teksti.toLowerCase().indexOf(term) >= 0) { hits.push(["Käsikirja", "#/kasikirja/" + c.id, c.otsikko]); } });
    D.paatokset.forEach(function (o) { if ((o.op + " " + o.nimi + " " + o.html).toLowerCase().indexOf(term) >= 0) { hits.push(["Päätös", "#/paatokset/" + o.op, o.op + " " + o.nimi]); } });
    D.kysymykset.forEach(function (x) { if ((x.q + " " + x.kuvaus).toLowerCase().indexOf(term) >= 0) { hits.push(["Kysymys", "#/kysymykset", x.q + " " + x.kuvaus.slice(0, 90)]); } });
    D.kokonaisuudet.forEach(function (p) { if ((p.kk + " " + p.nimi).toLowerCase().indexOf(term) >= 0) { hits.push(["Kokonaisuus", "#/kokonaisuus/" + p.kk, p.kk + " " + p.nimi]); } });
    if (D.sanasto.toLowerCase().indexOf(term) >= 0) { hits.push(["Sanasto", "#/sanasto", "Sanasto"]); }
    s += "<p>" + hits.length + " osumaa.</p><table><tbody>" + hits.map(function (h) { return "<tr><td>" + h[0] + '</td><td><a href="' + esc(h[1]) + '">' + esc(h[2]) + "</a></td></tr>"; }).join("") + "</tbody></table>";
    return s;
  }

  // ------------------------------------------------------------- router ---
  function parseHash() {
    var h = location.hash.replace(/^#\/?/, "");
    var qi = h.indexOf("?"); var path = qi >= 0 ? h.slice(0, qi) : h; var q = {};
    if (qi >= 0) { h.slice(qi + 1).split("&").forEach(function (kv) { if (!kv) { return; } var p = kv.split("="); q[decodeURIComponent(p[0])] = decodeURIComponent(p[1] || ""); }); }
    return { parts: path.split("/").filter(Boolean), q: q };
  }
  function route() {
    var r = parseHash(), p = r.parts, html = null;
    window.scrollTo(0, 0);
    switch (p[0] || "") {
      case "": html = viewSummary(); break;
      case "havainnot": html = viewFindings(r.q); break;
      case "kortti": html = viewCard(p[1], r.q); break;
      case "juurisyyt": html = viewRoots(); break;
      case "kokonaisuudet": html = viewPacks(); break;
      case "kokonaisuus": html = viewPack(p[1]); break;
      case "paatokset": html = viewOps(p[1]); break;
      case "kysymykset": html = viewQuestions(); break;
      case "eteneminen": html = viewProgress(); break;
      case "testaus": html = viewTesting(); break;
      case "kattavuus": html = viewCoverage(); break;
      case "kasikirja": html = viewHandbook(p[1]); break;
      case "sanasto": html = "<h1>Sanasto</h1>" + D.sanasto; break;
      case "haku": html = viewSearch(r.q); break;
      default: html = "<p>Tuntematon sivu.</p>";
    }
    if (html !== null) { main.innerHTML = html; }
    Array.prototype.forEach.call(document.querySelectorAll("#nav a"), function (a) {
      a.classList.toggle("active", a.getAttribute("href") === "#/" + (p[0] || ""));
    });
  }
  document.getElementById("hakulomake").addEventListener("submit", function (e) {
    e.preventDefault(); location.hash = "#/haku?q=" + encodeURIComponent(document.getElementById("haku").value);
  });
  var m = D.meta;
  var web = m.tila === "verkko";
  document.getElementById("tila").textContent = web ? "verkkoversio" : "paikallinen versio";
  if (SITE) {
    var back = document.getElementById("sivustolinkki");
    back.setAttribute("href", SITE + "laatu/"); back.hidden = false;
  }
  var prod = m.tuotantokoodi_muuttunut === 0 ? "tuotantokoodi ennallaan auditoinnin perusrevisiosta <code>" + esc(m.perusrevisio) + "</code>" :
    m.tuotantokoodi_muuttunut > 0 ? "<strong>tuotantokoodissa " + m.tuotantokoodi_muuttunut + " muuttunutta tiedostoa</strong> perusrevision <code>" + esc(m.perusrevisio) + "</code> jälkeen; viitteet koskevat niiden omaa revisiota" : "";
  document.getElementById("alatunniste").innerHTML = "Data tuotettu commitista <code>" + esc(m.commit) + "</code> (" + esc(m.tuotettu) +
    "), lähdetiiviste <code>" + esc(m.lahdetiiviste) + "</code>. Lähdeviitteiden revisiot: " + m.viiterevisiot.map(function (x) { return "<code>" + esc(x) + "</code>"; }).join(", ") +
    (prod ? " (" + prod + ")" : "") + ". Lähdekoodiviitteet ovat linkkejä GitHubiin väitteen revisiossa. " +
    (web ? "Verkkoversio on tuotettu dokumentaatiosivuston rakennuksessa samasta aineistosta kuin sivusto. "
      : "Ajantasaisuus: <code>python -I doc/arkkitehtuuri/tyokalut/portaali.py . --tarkista</code>. ") +
    "Portaali ei hae mitään verkosta.";
  window.addEventListener("hashchange", route);
  route();
})();
